package net.civeira.phylax.features.notification.smtpoutboundconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class SenderNameVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property sender name of smtp outbound config ")
  void test_sender_name_v_o_builder() {
    Assertions.assertFalse(SenderNameVO.nullValue().getSenderName().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(SenderNameVO.tryFrom(null).getSenderName().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", SenderNameVO.from("one").getSenderName().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> SenderNameVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", SenderNameVO.from("one").toString());
  }
}
